import{_ as e,o as a,c as d,a3 as s}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Targets and Tiers","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Targets and Tiers | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/targets"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/targets"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/targets"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/targets"}]]},"headers":[],"relativePath":"xclang/reference/targets.md","filePath":"en/xclang/reference/targets.md","lastUpdated":1791516064000}'),r={name:"xclang/reference/targets.md"};function o(n,t,i,c,l,h){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="targets-and-tiers" tabindex="-1">Targets and Tiers <a class="header-anchor" href="#targets-and-tiers" aria-label="Permalink to &quot;Targets and Tiers&quot;">​</a></h1><p>The hosts xclang runs on, the targets it builds for, and how each is tested. How to build for another target is in <a href="./../guide/cross-compiling">cross-compiling</a>.</p><h2 id="hosts" tabindex="-1">Hosts <a class="header-anchor" href="#hosts" aria-label="Permalink to &quot;Hosts&quot;">​</a></h2><p>A host is a machine the toolchain runs on. Each has its own archive, and every archive carries every target. The &quot;tested on&quot; column names the GitHub-hosted runner.</p><table tabindex="0"><thead><tr><th>host</th><th>archive built on</th><th>tested on</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td>Linux x64</td><td>ubuntu-24.04</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td>Linux x64, cross-compiled</td><td>ubuntu-24.04-arm</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td>Linux x64, cross-compiled; the toolchain is a MinGW program</td><td>windows-2025</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td>Linux x64, cross-compiled</td><td>windows-11-arm</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td>macOS arm64</td><td>macos-15</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td>macOS arm64, cross-compiled</td><td>macos-15-intel</td></tr></tbody></table><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>target</th><th>also spelled</th><th>C runtime</th><th>runs on</th><th>builds on</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td><code>x86_64-pc-linux-gnu</code>, <code>x86_64-linux-gnu</code> (Bazel)</td><td>glibc 2.17</td><td>glibc 2.17 or later</td><td>every host</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td><code>aarch64-pc-linux-gnu</code>, <code>aarch64-linux-gnu</code> (Bazel)</td><td>glibc 2.17</td><td>glibc 2.17 or later</td><td>every host</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td><code>x86_64-w64-windows-gnu</code>, <code>x86_64-pc-windows-gnu</code></td><td>mingw-w64 with UCRT</td><td>Windows 10 or later</td><td>every host</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td><code>aarch64-w64-windows-gnu</code>, <code>aarch64-pc-windows-gnu</code></td><td>mingw-w64 with UCRT</td><td>Windows 10 or later</td><td>every host</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td><code>arm64-apple-darwin</code>, <code>arm64-apple-macos</code>, <code>aarch64-apple-macosx</code>, ...</td><td>the SDK&#39;s libSystem</td><td>macOS 13.0 or later</td><td>macOS hosts; Linux and Windows hosts with the SDK <code>xclang</code> fetches</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td><code>x86_64-apple-macos</code>, <code>x86_64-apple-macosx</code></td><td>the SDK&#39;s libSystem</td><td>macOS 13.0 or later</td><td>macOS hosts; Linux and Windows hosts with the SDK <code>xclang</code> fetches</td></tr><tr><td><code>x86_64-pc-windows-msvc</code></td><td><code>x86_64-unknown-windows-msvc</code></td><td>Microsoft&#39;s CRT and STL, the hybrid CRT</td><td>Windows 10 or later</td><td>every host, with the SDK <code>xclang</code> fetches</td></tr><tr><td><code>aarch64-pc-windows-msvc</code></td><td><code>aarch64-unknown-windows-msvc</code></td><td>Microsoft&#39;s CRT and STL, the hybrid CRT</td><td>Windows 10 or later</td><td>every host, with the SDK <code>xclang</code> fetches</td></tr><tr><td><code>x86_64-unknown-linux-musl</code></td><td><code>x86_64-pc-linux-musl</code>, <code>x86_64-linux-musl</code></td><td>musl 1.2.6, linked statically</td><td>any Linux x64</td><td>every host, from 23.1.2.10 on</td></tr><tr><td><code>aarch64-unknown-linux-musl</code></td><td><code>aarch64-pc-linux-musl</code>, <code>aarch64-linux-musl</code></td><td>musl 1.2.6, linked statically</td><td>any Linux arm64</td><td>every host, from 23.1.2.10 on</td></tr></tbody></table><p>All of them are tier 1. The macOS targets need Apple&#39;s SDK, which comes from Xcode on macOS hosts (<a href="./../design/macos#the-sdk-is-xcode-s">macOS</a>). On Linux and Windows hosts they build with the SDK the user fetches from Apple (<a href="./../design/macos#the-sdk-on-linux-and-windows-hosts">macOS</a>), and CI runs those programs on arm64 and x64 Macs. The MSVC targets are tier 1 too: CI runs their programs on Windows x64 and arm64 runners (<a href="./../integrations/clang#msvc-targets">MSVC targets</a>). So are the musl targets, which every archive carries from 23.1.2.10 on: their programs are static, need no glibc, and run on the Linux x64 and arm64 runners (<a href="#musl-targets">musl</a>).</p><h2 id="what-each-target-has" tabindex="-1">What Each Target Has <a class="header-anchor" href="#what-each-target-has" aria-label="Permalink to &quot;What Each Target Has&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Linux</th><th>Linux (musl)</th><th>Windows (MinGW)</th><th>macOS</th><th>Windows (MSVC)</th></tr></thead><tbody><tr><td>C library</td><td>glibc 2.17, the system&#39;s</td><td>musl, static</td><td>UCRT, the system&#39;s</td><td>libSystem, the system&#39;s</td><td>UCRT, the system&#39;s</td></tr><tr><td>C++ library</td><td>libc++, libc++abi, static</td><td>libc++, libc++abi, static</td><td>libc++, libc++abi, static</td><td>libc++, libc++abi, static (not the system&#39;s <code>libc++.dylib</code>)</td><td>Microsoft&#39;s STL, static</td></tr><tr><td>unwinder</td><td>libunwind, static</td><td>libunwind, static</td><td>libunwind, static</td><td>the system&#39;s (libSystem)</td><td>the VC runtime&#39;s, static</td></tr><tr><td>compiler-rt builtins, profile</td><td><span class="status-badge ok">Supported</span></td><td><span class="status-badge ok">Supported</span></td><td><span class="status-badge ok">Supported</span></td><td><span class="status-badge ok">Supported</span></td><td><span class="status-badge ok">Supported</span></td></tr><tr><td>ASan, TSan, LSan, UBSan, libFuzzer</td><td><span class="status-badge ok">Supported</span></td><td>UBSan only</td><td><span class="status-badge note">Considered</span></td><td><span class="status-badge ok">Supported</span></td><td>Supported: UBSan; ASan and libFuzzer for x64</td></tr><tr><td>ASan libc++</td><td><span class="status-badge ok">Supported</span></td><td>none</td><td><span class="status-badge note">Considered</span></td><td><span class="status-badge ok">Supported</span></td><td>none: the STL</td></tr><tr><td>linker</td><td>ld.lld</td><td>ld.lld</td><td>ld.lld (MinGW driver)</td><td>ld64.lld; <code>-fuse-ld=ld</code> for Apple&#39;s, without LTO</td><td>lld-link</td></tr></tbody></table><p>Sanitizers for the MinGW targets are <a href="./../design/roadmap#mingw-sanitizers">considered</a>; those of the MSVC targets are in <a href="./../features/sanitizers#msvc-targets">sanitizers</a>, those of musl in <a href="./../features/sanitizers#musl-targets">sanitizers</a>.</p><h2 id="musl-targets" tabindex="-1">musl Targets <a class="header-anchor" href="#musl-targets" aria-label="Permalink to &quot;musl Targets&quot;">​</a></h2><p><code>x86_64-unknown-linux-musl</code> and <code>aarch64-unknown-linux-musl</code>, from 23.1.2.10 on, link musl and every runtime into the program, as Rust&#39;s targets of the same names do. The program has no program interpreter and no dynamic section: it takes nothing from the system it runs on, glibc included, and runs on any Linux distribution of its architecture.</p><ul><li><strong>musl 1.2.6</strong>, with the patches of musl&#39;s security advisories against it, built by xclang, and the UAPI headers of Linux 6.18, the newest long-term kernel (<a href="./layout#sysroots">layout</a>).</li><li><strong>Static by default</strong>: the config file passes <code>-static</code>, so a program is an <code>EXEC</code> file. <code>-static-pie</code> makes it position-independent, for address space layout randomization of the program itself; that cost 5% more size and 2 to 5% more time to start a hello world in C and C++, measured on Linux x64. A <code>-static-pie</code> in the config file would have made <code>-no-pie</code> an error, which CMake and rustc pass.</li><li><strong>No shared libraries</strong>: there is no <code>libc.so</code>, so no dynamic linking against musl, no <code>dlopen</code> of a library, and no <code>-shared</code> library for a musl system such as Alpine.</li><li><strong>UBSan only</strong>, of the sanitizers (<a href="./../features/sanitizers#musl-targets">sanitizers</a>).</li></ul><p>How musl behaves apart from glibc (locales, DNS, <code>malloc</code>) is in <a href="./compatibility#known-limitations">compatibility</a>.</p><h2 id="tiers" tabindex="-1">Tiers <a class="header-anchor" href="#tiers" aria-label="Permalink to &quot;Tiers&quot;">​</a></h2><p>Each target has a tier, as Rust&#39;s targets do. The tier says how a target is tested, and so how much a release promises about it.</p><ul><li><strong>Tier 1</strong>: built for every release, and its tests run on a GitHub-hosted runner of the target itself; a failure stops the release.</li><li><strong>Tier 2</strong>: built for every release, and its tests run under emulation or virtualization: qemu, a virtual machine, Android&#39;s emulator, Apple&#39;s simulators.</li><li><strong>Tier 3</strong>: programs are compiled and linked for it, not run.</li></ul><p>For the targets of every archive, that means programs built on every host run on a runner of their target, with no emulator (<a href="./../dev/testing#cross-compiling">testing</a>).</p><h2 id="not-yet-supported" tabindex="-1">Not Yet Supported <a class="header-anchor" href="#not-yet-supported" aria-label="Permalink to &quot;Not Yet Supported&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>status</th></tr></thead><tbody><tr><td><a href="./../design/roadmap#mingw-sanitizers">Sanitizers for MinGW targets</a></td><td><span class="status-badge note">Considered</span></td></tr></tbody></table><p>Every other target, with its planned tier and its status, is in the <a href="./../design/roadmap#targets">roadmap</a>.</p>',22)])])}const m=e(r,[["render",o]]);export{p as __pageData,m as default};
